-- Public, curated source registry for EDUNEXUS knowledge discovery.
-- This registers metadata and editorial summaries only; it does NOT claim full-text ingestion.
BEGIN;
CREATE TABLE IF NOT EXISTS public.knowledge_source_registry (
 source_id text PRIMARY KEY,
 title text NOT NULL,
 publisher text NOT NULL,
 canonical_url text NOT NULL,
 domain text NOT NULL,
 trust_tier text NOT NULL CHECK (trust_tier IN ('A','B','C')),
 intended_use text NOT NULL,
 license_notes text NOT NULL,
 agent_roles text[] NOT NULL DEFAULT ARRAY[]::text[],
 editorial_summary text NOT NULL,
 registry_version text NOT NULL,
 ingestion_status text NOT NULL DEFAULT 'metadata_registered' CHECK (ingestion_status IN ('metadata_registered','full_text_reviewed','indexed','blocked')),
 last_verified_at timestamptz,
 created_at timestamptz NOT NULL DEFAULT now(),
 updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.knowledge_source_registry ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS knowledge_source_registry_public_read ON public.knowledge_source_registry;
CREATE POLICY knowledge_source_registry_public_read ON public.knowledge_source_registry FOR SELECT USING (true);
GRANT SELECT ON public.knowledge_source_registry TO anonymous, authenticated;
